import "dotenv/config";
import {
  beforeEach,
  afterEach,
  afterAll,
  describe,
  it,
  expect,
  vi,
} from "vitest";
import { randomUUID } from "node:crypto";
import { db } from "@/lib/db";
import { countQuotaUsage } from "@/lib/delivery-usage";
import { createCampaign } from "@/lib/campaigns";
import { encryptToken } from "@/lib/crypto";

const mocks = vi.hoisted(() => ({
  send: vi.fn(),
  list: vi.fn(),
  get: vi.fn(),
  thread: vi.fn(),
}));
vi.mock("@/lib/gmail", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@/lib/gmail")>();
  return {
    ...actual,
    gmailForUser: vi.fn(async () => ({
      email: "[REDACTED_EMAIL]",
      name: "Anoop Jha",
      gmail: {
        users: {
          messages: { send: mocks.send, list: mocks.list, get: mocks.get },
          threads: { get: mocks.thread },
        },
      },
    })),
  };
});
import {
  deliverOne,
  checkReplies,
  replyCandidates,
  dispatchPending,
  inngest,
} from "@/lib/inngest";
import { buildMime } from "@/lib/gmail";
import { storeLocalResume, cleanupAttachments } from "@/lib/storage";

const enabled = process.env.MAILLOOP_DB_TESTS === "1";
if (
  enabled &&
  !["localhost", "127.0.0.1"].includes(
    new URL(process.env.DATABASE_URL!).hostname,
  )
)
  throw new Error("Database integration tests require a local database.");
let userId: string;
let otherId: string;
let templateId: string;
let contactId: string;
const request = (recipientIds = [contactId], extra = {}) => ({
  templateId,
  recipientIds,
  recipientRoles: Object.fromEntries(
    recipientIds.map((id) => [id, "Engineer"]),
  ),
  attachResume: false,
  idempotencyKey: randomUUID(),
  ...extra,
});

describe.runIf(enabled)(
  "database-backed campaign and delivery guarantees (Gmail mocked)",
  () => {
    beforeEach(async () => {
      vi.clearAllMocks();
      mocks.send.mockResolvedValue({
        data: { id: "gmail-message", threadId: "gmail-thread" },
      });
      mocks.list.mockResolvedValue({ data: { messages: [] } });
      mocks.get.mockResolvedValue({
        data: { internalDate: String(Date.now()) },
      });
      mocks.thread.mockResolvedValue({ data: { messages: [] } });
      userId = randomUUID();
      otherId = randomUUID();
      await db.user.createMany({
        data: [userId, otherId].map((id) => ({
          id,
          email: `${id}@example.test`,
          gmailAuthorized: true,
          planOverride: "PAID",
          planOverrideStartsAt: new Date(0),
          planOverrideReason: "Campaign override fixture",
          gmailScopes: [
            "https://www.googleapis.com/auth/gmail.send",
            "https://www.googleapis.com/auth/gmail.readonly",
          ],
          encryptedRefreshToken: encryptToken("fake-test-token", id),
        })),
      });
      const template = await db.template.create({
        data: {
          userId,
          name: "Introduction",
          subject: "{{role}} at {{company}}",
          body: "Hi {{name}},\nI’d like to help {{company}}.",
        },
      });
      templateId = template.id;
      const contact = await db.contact.create({
        data: {
          userId,
          name: "Alex",
          email: "[REDACTED_EMAIL]",
          company: "Acme",
        },
      });
      contactId = contact.id;
    });
    afterEach(async () => {
      expect(mocks.list).not.toHaveBeenCalled();
      expect(mocks.get).not.toHaveBeenCalled();
      expect(mocks.thread).not.toHaveBeenCalled();
      vi.restoreAllMocks();
      await db.campaign.deleteMany({
        where: { userId: { in: [userId, otherId] } },
      });
      for (const id of [userId, otherId]) {
        await db.user.updateMany({
          where: { id },
          data: { currentAttachmentId: null },
        });
        await cleanupAttachments(id);
      }
      await db.user.deleteMany({ where: { id: { in: [userId, otherId] } } });
    });
    afterAll(async () => {
      await db.$disconnect();
    });
    it("snapshots mixed roles, links, and explicit PDF choices independently", async () => {
      await db.contact.updateMany({
        where: { id: contactId, userId },
        data: { jobRole: "SDE Intern" },
      });
      const second = await db.contact.create({
        data: {
          userId,
          name: "Sam",
          email: "[REDACTED_EMAIL]",
          jobRole: "Frontend Developer",
        },
      });
      await db.template.updateMany({
        where: { id: templateId, userId },
        data: {
          body: "Hi {{name}}: {{role}}.\n\nhttps://example.com/first?a=1&b=2\nhttps://github.com/user\nhttps://linkedin.com/in/user\n\nEnd.",
        },
      });
      const pdf = Buffer.from("%PDF-1.4\n%%EOF");
      await storeLocalResume(
        userId,
        new File([pdf], "first.pdf", { type: "application/pdf" }),
      );
      const campaign = await createCampaign(
        userId,
        request([contactId, second.id], {
          recipientRoles: { [second.id]: "Backend Developer" },
          attachResume: false,
        }),
      );
      const saved = await db.campaign.findFirstOrThrow({
        where: { id: campaign.id, userId },
        include: { sends: true },
      });
      expect(saved.attachmentId).toBeNull();
      expect(saved.sends.map((s) => s.recipientRole).sort()).toEqual([
        "Backend Developer",
        "SDE Intern",
      ]);
      expect(
        saved.sends.every(
          (s) =>
            s.body ===
            `Hi ${s.recipientName}: ${s.recipientRole}.\n\nhttps://example.com/first?a=1&b=2\nhttps://github.com/user\nhttps://linkedin.com/in/user\n\nEnd.`,
        ),
      ).toBe(true);
      await db.template.updateMany({
        where: { id: templateId, userId },
        data: { body: "https://example.com/second" },
      });
      await db.contact.updateMany({
        where: { id: second.id, userId },
        data: { jobRole: "Designer" },
      });
      expect(
        (
          await db.send.findMany({
            where: { campaignId: campaign.id, campaign: { userId } },
          })
        ).every((s) => s.body.includes("https://example.com/first")),
      ).toBe(true);
      await deliverOne(userId, saved.sends[0].id);
      const mime = Buffer.from(
        mocks.send.mock.calls[0][0].requestBody.raw,
        "base64url",
      ).toString();
      expect(mime).not.toContain("application/pdf");
    });
    it("requires legacy roles, resolved placeholders, and an owned current PDF", async () => {
      await expect(
        createCampaign(userId, request([contactId], { recipientRoles: {} })),
      ).rejects.toThrow("job role");
      await expect(
        createCampaign(userId, request([contactId], { attachResume: true })),
      ).rejects.toThrow("PDF");
      await db.template.updateMany({
        where: { id: templateId, userId },
        data: { body: "{{link}}" },
      });
      for (const body of [
        "{{link}}",
        "{{ link }}",
        "{{\nlink\t}}",
        "{{unknown}}",
      ]) {
        await db.template.updateMany({
          where: { id: templateId, userId },
          data: { body },
        });
        await expect(createCampaign(userId, request())).rejects.toThrow(
          body.includes("link")
            ? "Replace {{link}} with a URL directly in your message."
            : "Use {{name}}",
        );
        expect(await db.campaign.count({ where: { userId } })).toBe(0);
      }
      await db.template.updateMany({
        where: { id: templateId, userId },
        data: { body: "https://example.com/resume" },
      });
      await expect(
        createCampaign(
          userId,
          request([contactId], { recipientRoles: { [otherId]: "Engineer" } }),
        ),
      ).rejects.toThrow("selected recipients");
      const foreign = await db.attachment.create({
        data: {
          userId: otherId,
          fileName: "foreign.pdf",
          storagePath: "foreign",
        },
      });
      await db.user.update({
        where: { id: userId },
        data: { currentAttachmentId: foreign.id },
      });
      await expect(
        createCampaign(userId, request([contactId], { attachResume: true })),
      ).rejects.toThrow("PDF");
      expect(await db.campaign.count({ where: { userId } })).toBe(0);
    });
    it("recovers failed event publication with one stable event per recipient", async () => {
      const second = await db.contact.create({
        data: { userId, name: "Sam", email: "[REDACTED_EMAIL]" },
      });
      await createCampaign(userId, request([contactId, second.id]));
      const publish = vi
        .spyOn(inngest, "send")
        .mockRejectedValueOnce(new Error("queue unavailable"))
        .mockResolvedValue({ ids: ["event-a", "event-b"] });
      await expect(dispatchPending(userId)).rejects.toThrow(
        "QUEUE_PUBLICATION_FAILED",
      );
      expect(
        await db.send.count({
          where: { campaign: { userId }, dispatchedAt: null },
        }),
      ).toBe(2);
      expect(await dispatchPending(userId, new Date(Date.now() + 300001))).toBe(
        2,
      );
      expect(publish.mock.calls[0][0]).not.toEqual(publish.mock.calls[1][0]);
      const events = publish.mock.calls[1][0] as {
        id: string;
        data: { userId: string; sendId: string };
      }[];
      expect(events).toHaveLength(2);
      expect(new Set(events.map((e) => e.id)).size).toBe(2);
      expect(events.every((e) => e.data.userId === userId)).toBe(true);
      expect(
        await db.send.count({
          where: { campaign: { userId }, dispatchedAt: null },
        }),
      ).toBe(0);
    });
    it("rejects removed recipients in stale campaign selections", async () => {
      await db.contact.updateMany({
        where: { id: contactId, userId },
        data: { shortlistRemovedAt: new Date() },
      });
      await expect(createCampaign(userId, request())).rejects.toThrow(
        "One or more contacts are unavailable.",
      );
      expect(await db.campaign.count({ where: { userId } })).toBe(0);
      await db.contact.updateMany({
        where: { id: contactId, userId },
        data: { shortlistRemovedAt: null },
      });
      expect((await createCampaign(userId, request())).count).toBe(1);
    });

    it("snapshots messages and rejects another user’s template/contact", async () => {
      await expect(createCampaign(otherId, request())).rejects.toThrow(
        "template",
      );
      const otherContact = await db.contact.create({
        data: { userId: otherId, name: "Other", email: "[REDACTED_EMAIL]" },
      });
      await expect(
        createCampaign(userId, request([otherContact.id])),
      ).rejects.toThrow("contacts");
      const campaign = await createCampaign(userId, request());
      await db.template.updateMany({
        where: { id: templateId, userId },
        data: { body: "Changed" },
      });
      const send = await db.send.findFirstOrThrow({
        where: { campaignId: campaign.id, campaign: { userId } },
      });
      expect(send.body).toContain("Hi Alex");
      expect(send.subject).toBe("Engineer at Acme");
    });
    it("makes repeated submissions idempotent under concurrent requests", async () => {
      const input = request();
      const [a, b] = await Promise.all([
        createCampaign(userId, input),
        createCampaign(userId, input),
      ]);
      expect(a.id).toBe(b.id);
      expect(await db.send.count({ where: { campaign: { userId } } })).toBe(1);
    });
    it("blocks queued repeats, allows explicit sent repeats, and preserves address protection after edits", async () => {
      const campaign = await createCampaign(userId, request());
      await db.contact.updateMany({
        where: { id: contactId, userId },
        data: { email: "[REDACTED_EMAIL]" },
      });
      await expect(
        createCampaign(
          userId,
          request([], { recipientIds: [contactId], resendIds: [contactId] }),
        ),
      ).rejects.toThrow("skipped");
      await db.contact.updateMany({
        where: { id: contactId, userId },
        data: { email: "[REDACTED_EMAIL]" },
      });
      await db.send.updateMany({
        where: { campaignId: campaign.id, campaign: { userId } },
        data: { status: "SENT", deliveryState: "DONE", sentAt: new Date() },
      });
      await expect(createCampaign(userId, request())).rejects.toThrow(
        "skipped",
      );
      await db.contact.updateMany({
        where: { id: contactId, userId },
        data: { email: "[REDACTED_EMAIL]" },
      });
      const replacement = await db.contact.create({
        data: { userId, name: "Alex Again", email: "[REDACTED_EMAIL]" },
      });
      await expect(
        createCampaign(userId, request([replacement.id])),
      ).rejects.toThrow("skipped");
      expect((await createCampaign(userId, request([contactId]))).count).toBe(
        1,
      );
      expect(
        (
          await createCampaign(
            userId,
            request([replacement.id], {
              resendIds: [replacement.id],
            }),
          )
        ).count,
      ).toBe(1);
    });
    it("allows identical names, unsuccessful sends, missing snapshots, and another user's history", async () => {
      const campaign = await db.campaign.create({
        data: { userId, templateId, status: "COMPLETED" },
      });
      await db.send.createMany({
        data: ["SENT", "FAILED", "CANCELLED"].map((status) => ({
          campaignId: campaign.id,
          contactId,
          recipientEmail: status === "SENT" ? "" : "[REDACTED_EMAIL]",
          recipientName: "Alex",
          status: status as "SENT" | "FAILED" | "CANCELLED",
          deliveryState: "DONE" as const,
        })),
      });
      const otherContact = await db.contact.create({
        data: { userId: otherId, name: "Alex", email: "[REDACTED_EMAIL]" },
      });
      const otherCampaign = await db.campaign.create({
        data: { userId: otherId, templateId, status: "COMPLETED" },
      });
      await db.send.create({
        data: {
          campaignId: otherCampaign.id,
          contactId: otherContact.id,
          recipientEmail: "[REDACTED_EMAIL]",
          status: "SENT",
          deliveryState: "DONE",
        },
      });
      const sameName = await db.contact.create({
        data: { userId, name: "Alex", email: "[REDACTED_EMAIL]" },
      });
      expect(
        (await createCampaign(userId, request([contactId, sameName.id]))).count,
      ).toBe(2);
    });
    it("admits only one request for the final reserved quota slot", async () => {
      const history = await db.campaign.create({
        data: { userId, templateId, status: "SENDING" },
      });
      await db.send.createMany({
        data: Array.from({ length: 199 }, () => ({
          campaignId: history.id,
          contactId,
          recipientEmail: "[REDACTED_EMAIL]",
        })),
      });
      const contacts = await db.contact.createManyAndReturn({
        data: ["one", "two"].map((name) => ({
          userId,
          name,
          email: `${name}@example.test`,
        })),
      });
      const results = await Promise.allSettled(
        contacts.map((c) => createCampaign(userId, request([c.id]))),
      );
      expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
      expect(await countQuotaUsage(userId)).toBe(200);
    });
    it("counts rolling success timestamps, queued rows, and uncertain attempts", async () => {
      const history = await db.campaign.create({
        data: { userId, templateId, status: "COMPLETED" },
      });
      await db.send.createMany({
        data: [
          {
            campaignId: history.id,
            contactId,
            status: "SENT",
            deliveryState: "DONE",
            sentAt: new Date(Date.now() - 25 * 3600000),
          },
          {
            campaignId: history.id,
            contactId,
            status: "REPLIED",
            deliveryState: "DONE",
            sentAt: new Date(),
          },
          {
            campaignId: history.id,
            contactId,
            status: "FAILED",
            deliveryState: "UNCERTAIN",
          },
          {
            campaignId: history.id,
            contactId,
            status: "FAILED",
            deliveryState: "DONE",
          },
        ],
      });
      expect(await countQuotaUsage(userId)).toBe(2);
    });
    it("recovers rolling capacity without clearing history and preserves old reservations", async () => {
      const now = new Date();
      const history = await db.campaign.create({
        data: { userId, templateId, status: "COMPLETED" },
      });
      const recent = new Date(now.getTime() - 23 * 3600000);
      await db.send.createMany({
        data: (
          [
            { status: "SENT", deliveryState: "DONE", sentAt: recent },
            { status: "REPLIED", deliveryState: "DONE", sentAt: recent },
            { status: "QUEUED", deliveryState: "READY" },
            { status: "QUEUED", deliveryState: "ATTEMPTING" },
            { status: "FAILED", deliveryState: "UNCERTAIN" },
            { status: "FAILED", deliveryState: "DONE" },
            { status: "CANCELLED", deliveryState: "DONE" },
          ] as const
        ).map((row) => ({
          ...row,
          campaignId: history.id,
          contactId,
          createdAt: new Date(now.getTime() - 48 * 3600000),
        })),
      });
      const otherCampaign = await db.campaign.create({
        data: { userId: otherId, templateId, status: "QUEUED" },
      });
      await db.send.create({
        data: { campaignId: otherCampaign.id, contactId },
      });
      expect(await countQuotaUsage(userId, db, now)).toBe(4);
      const later = new Date(now.getTime() + 2 * 3600000);
      expect(await countQuotaUsage(userId, db, later)).toBe(2);
      await db.send.updateMany({
        where: { campaignId: history.id, deliveryState: "UNCERTAIN" },
        data: { deliveryState: "DONE" },
      });
      await db.send.updateMany({
        where: { campaignId: history.id, deliveryState: "READY" },
        data: { status: "CANCELLED", deliveryState: "DONE" },
      });
      expect(await countQuotaUsage(userId, db, later)).toBe(1);
      expect(await db.send.count({ where: { campaignId: history.id } })).toBe(
        7,
      );
    });

    it("rejects pre-existing queues above the lowered cap then sends at exactly 200", async () => {
      const history = await db.campaign.create({
        data: { userId, templateId, status: "QUEUED" },
      });
      await db.send.createMany({
        data: Array.from({ length: 201 }, () => ({
          campaignId: history.id,
          contactId,
          recipientEmail: "[REDACTED_EMAIL]",
        })),
      });
      const sends = await db.send.findMany({
        where: { campaignId: history.id },
      });
      await deliverOne(userId, sends[0].id);
      expect(mocks.send).not.toHaveBeenCalled();
      expect(
        await db.send.findUniqueOrThrow({ where: { id: sends[0].id } }),
      ).toMatchObject({ status: "FAILED", deliveryState: "DONE" });
      expect(await countQuotaUsage(userId)).toBe(200);
      await deliverOne(userId, sends[1].id);
      expect(mocks.send).toHaveBeenCalledTimes(1);
      expect(await countQuotaUsage(userId)).toBe(200);
    });

    it("paces separate campaigns for one user and never sends a completed job twice", async () => {
      const second = await db.contact.create({
        data: { userId, name: "Sam", email: "[REDACTED_EMAIL]" },
      });
      const firstCampaign = await createCampaign(userId, request());
      const secondCampaign = await createCampaign(userId, request([second.id]));
      const a = await db.send.findFirstOrThrow({
        where: { campaignId: firstCampaign.id, campaign: { userId } },
      });
      const b = await db.send.findFirstOrThrow({
        where: { campaignId: secondCampaign.id, campaign: { userId } },
      });
      expect((await deliverOne(userId, a.id)).outcome).toBe("done");
      const user = await db.user.findUniqueOrThrow({ where: { id: userId } });
      const delay = user.nextSendAt!.getTime() - Date.now();
      expect(delay).toBeGreaterThan(4000);
      expect(delay).toBeLessThanOrEqual(5000);
      expect((await deliverOne(userId, b.id)).outcome).toBe("wait");
      await deliverOne(userId, a.id);
      expect(mocks.send).toHaveBeenCalledTimes(1);
    });
    it("leaves ambiguous delivery in manual review without reading or sending again", async () => {
      const campaign = await createCampaign(userId, request());
      const send = await db.send.findFirstOrThrow({
        where: { campaignId: campaign.id, campaign: { userId } },
      });
      mocks.send.mockRejectedValueOnce(new Error("timeout"));
      expect((await deliverOne(userId, send.id)).outcome).toBe("uncertain");
      expect((await deliverOne(userId, send.id)).outcome).toBe("uncertain");
      expect(
        await db.send.findFirst({
          where: { id: send.id, campaign: { userId } },
        }),
      ).toMatchObject({
        status: "FAILED",
        deliveryState: "UNCERTAIN",
        gmailMessageId: null,
      });
      expect(mocks.send).toHaveBeenCalledTimes(1);
      expect(mocks.list).not.toHaveBeenCalled();
      expect(mocks.get).not.toHaveBeenCalled();
    });
    it("starts immediately and enforces the exact five-second boundary across campaigns", async () => {
      const now = Date.now();
      const clock = vi.spyOn(Date, "now").mockReturnValue(now);
      const a = await createCampaign(userId, request());
      const second = await db.contact.create({
        data: { userId, name: "Sam", email: "[REDACTED_EMAIL]" },
      });
      const b = await createCampaign(userId, request([second.id]));
      const sends = await db.send.findMany({
        where: { campaignId: { in: [a.id, b.id] }, campaign: { userId } },
      });
      const firstSend = sends.find((s) => s.campaignId === a.id)!;
      const secondSend = sends.find((s) => s.campaignId === b.id)!;
      expect(await deliverOne(userId, firstSend.id)).toEqual({
        outcome: "done",
      });
      clock.mockReturnValue(now + 4999);
      expect(await deliverOne(userId, secondSend.id)).toEqual({
        outcome: "wait",
        until: now + 5000,
      });
      expect(mocks.send).toHaveBeenCalledTimes(1);
      clock.mockReturnValue(now + 5000);
      expect(await deliverOne(userId, secondSend.id)).toEqual({
        outcome: "done",
      });
      expect(mocks.send).toHaveBeenCalledTimes(2);
    });
    it("preserves an existing account wait and leaves other users independent", async () => {
      const now = Date.now();
      vi.spyOn(Date, "now").mockReturnValue(now);
      await db.user.update({
        where: { id: userId },
        data: { nextSendAt: new Date(now + 90000) },
      });
      const a = await createCampaign(userId, request());
      const send = await db.send.findFirstOrThrow({
        where: { campaignId: a.id, campaign: { userId } },
      });
      expect(await deliverOne(userId, send.id)).toEqual({
        outcome: "wait",
        until: now + 90000,
      });
      const otherTemplate = await db.template.create({
        data: { userId: otherId, name: "Other", subject: "Hi", body: "Hello" },
      });
      const otherContact = await db.contact.create({
        data: {
          userId: otherId,
          name: "Other",
          email: "[REDACTED_EMAIL]",
        },
      });
      const b = await createCampaign(otherId, {
        ...request([otherContact.id]),
        templateId: otherTemplate.id,
      });
      const otherSend = await db.send.findFirstOrThrow({
        where: { campaignId: b.id, campaign: { userId: otherId } },
      });
      expect(await deliverOne(otherId, otherSend.id)).toEqual({
        outcome: "done",
      });
      expect(mocks.send).toHaveBeenCalledTimes(1);
      expect(
        (
          await db.user.findUniqueOrThrow({ where: { id: userId } })
        ).nextSendAt?.getTime(),
      ).toBe(now + 90000);
    });
    it.each([429, 403])(
      "persists a %i cooldown across campaigns after one failed attempt",
      async (status) => {
        let now = Date.now();
        const clock = vi.spyOn(Date, "now").mockImplementation(() => now);
        const a = await createCampaign(userId, request());
        const second = await db.contact.create({
          data: { userId, name: "Sam", email: "[REDACTED_EMAIL]" },
        });
        const b = await createCampaign(userId, request([second.id]));
        const firstSend = await db.send.findFirstOrThrow({
          where: { campaignId: a.id, campaign: { userId } },
        });
