describe("MIME composition", () => {
  it.each([
    ["Anoop Jha", "Anoop Jha <[REDACTED_EMAIL]>"],
    ['Doe, "Alex"', '"Doe, \\"Alex\\"" <[REDACTED_EMAIL]>'],
    [null, "[REDACTED_EMAIL]"],
    ["   ", "[REDACTED_EMAIL]"],
  ])("formats sender name %j safely", async (fromName, expected) => {
    const raw = await buildMime({
      from: "[REDACTED_EMAIL]",
      fromName,
      to: "[REDACTED_EMAIL]",
      subject: "Hello",
      body: "Hi Alex",
      messageId: "<[REDACTED_EMAIL]>",
    });
    const mime = Buffer.from(raw, "base64url").toString();
    expect(mime.split("\r\n")).toContain(`From: ${expected}`);
  });

  it("encodes an international sender name as UTF-8", async () => {
    const raw = await buildMime({
      from: "[REDACTED_EMAIL]",
      fromName: "अनूप झा",
      to: "[REDACTED_EMAIL]",
      subject: "Hello",
      body: "Hi Alex",
      messageId: "<[REDACTED_EMAIL]>",
    });
    const mime = Buffer.from(raw, "base64url").toString();
    expect(mime).toContain(
      `From: =?UTF-8?B?${Buffer.from("अनूप झा").toString("base64")}?= <[REDACTED_EMAIL]>`,
    );
  });

  it("builds one To recipient, no CC/BCC, UTF-8 content, and a PDF part", async () => {
    const raw = await buildMime({
      from: "[REDACTED_EMAIL]",
      to: "[REDACTED_EMAIL]",
      subject: "Hello 世界",
      body: "Hi Alex 👋",
      messageId: "<[REDACTED_EMAIL]>",
      attachment: {
        fileName: "resume.pdf",
        bytes: Buffer.from("%PDF-1.4\n%%EOF"),
      },
    });
    const mime = Buffer.from(raw, "base64url").toString();
    expect((mime.match(/^To:/gm) ?? []).length).toBe(1);
    expect(mime).not.toMatch(/^(Cc|Bcc):/m);
    expect(mime).toContain("application/pdf");
    expect(mime).toContain("<[REDACTED_EMAIL]>");
    expect(mime).toContain("charset=utf-8");
    expect(raw).not.toMatch(/[+/=]/);
  });
});
